-- Migration 008: 24 real, local Georgia/Atlanta-metro organizations,
-- researched individually (not scraped from any directory). Pure inserts with
-- fixed ids - safe to re-run, existing rows untouched.

insert into public.organizations
  (id, owner_id, name, description, website, logo_url, category, tags, remote, international,
   min_age, country, state, city, verified, counts_for_service_hours, commitment_type, featured)
values
  ('a1000000-0000-4000-8000-000000000001', null, 'HOPE Atlanta', 'A homelessness prevention and services agency working across Atlanta to keep families housed and help people experiencing homelessness get back on their feet.', 'https://hopeatlanta.org', 'https://www.google.com/s2/favicons?domain=hopeatlanta.org&sz=128', 'community', array['good for crews', 'counts for school hours'], false, false, 14, 'United States', 'GA', 'Atlanta', true, true, 'ongoing', false),
  ('a1000000-0000-4000-8000-000000000002', null, 'Atlanta Mission', 'The largest provider of services to men, women, and children experiencing homelessness in Atlanta, running shelters, recovery programs, and thrift stores across the city.', 'https://atlantamission.org', 'https://www.google.com/s2/favicons?domain=atlantamission.org&sz=128', 'community', array['good for crews', 'family friendly'], false, false, 13, 'United States', 'GA', 'Atlanta', true, true, 'both', false),
  ('a1000000-0000-4000-8000-000000000003', null, 'Covenant House Georgia', 'Part of a national network providing shelter, food, and support services to young people facing homelessness, with a campus based in Atlanta.', 'https://covenanthousega.org', 'https://www.google.com/s2/favicons?domain=covenanthousega.org&sz=128', 'community', array['recurring'], false, false, 18, 'United States', 'GA', 'Atlanta', true, true, 'ongoing', false),
  ('a1000000-0000-4000-8000-000000000004', null, 'Pebble Tossers', 'A youth-focused nonprofit built specifically to connect kids, teens, and families with vetted volunteer opportunities across more than 60 metro Atlanta nonprofits.', 'https://pebbletossers.org', 'https://www.google.com/s2/favicons?domain=pebbletossers.org&sz=128', 'community', array['family friendly', 'counts for school hours', 'leadership role'], false, false, 11, 'United States', 'GA', 'Atlanta', true, true, 'both', false),
  ('a1000000-0000-4000-8000-000000000005', null, 'Trees Atlanta', 'A nonprofit conservation organization that protects and improves Atlanta urban tree canopy through planting, care, and education, running volunteer projects nearly every week of the year.', 'https://www.treesatlanta.org', 'https://www.google.com/s2/favicons?domain=www.treesatlanta.org&sz=128', 'environment', array['outdoors', 'physical work', 'recurring'], false, false, 12, 'United States', 'GA', 'Atlanta', true, true, 'ongoing', false),
  ('a1000000-0000-4000-8000-000000000006', null, 'Chattahoochee National Park Conservancy', 'The nonprofit partner of the Chattahoochee River National Recreation Area, supporting trail restoration and river cleanup along the Chattahoochee.', 'https://www.chattahoocheeparks.org', 'https://www.google.com/s2/favicons?domain=www.chattahoocheeparks.org&sz=128', 'environment', array['outdoors', 'physical work', 'good for crews'], false, false, 14, 'United States', 'GA', 'Atlanta', true, true, 'both', false),
  ('a1000000-0000-4000-8000-000000000007', null, 'EarthShare Georgia', 'A coalition of environmental and conservation nonprofits across Georgia, coordinating volunteer projects and workplace giving campaigns for the state environmental movement.', 'https://earthsharega.org', 'https://www.google.com/s2/favicons?domain=earthsharega.org&sz=128', 'environment', array['outdoors', 'good for crews'], false, false, 14, 'United States', 'GA', 'Atlanta', true, true, 'both', false),
  ('a1000000-0000-4000-8000-000000000008', null, 'Georgia Wildlife Federation', 'A statewide conservation organization working to protect Georgia wildlife and habitat through education, restoration projects, and advocacy.', 'https://gwf.org', 'https://www.google.com/s2/favicons?domain=gwf.org&sz=128', 'environment', array['outdoors', 'good for crews'], false, false, 14, 'United States', 'GA', 'Georgia', true, true, 'both', false),
  ('a1000000-0000-4000-8000-000000000009', null, 'Children''s Healthcare of Atlanta', 'One of the largest pediatric healthcare systems in the country, running a structured summer VolunTEEN program that lets high schoolers see hospital life firsthand.', 'https://www.choa.org', 'https://www.google.com/s2/favicons?domain=www.choa.org&sz=128', 'medicine', array['counts for school hours', 'recurring'], false, false, 15, 'United States', 'GA', 'Atlanta', true, true, 'one-time', false),
  ('a1000000-0000-4000-8000-000000000010', null, 'Piedmont Atlanta Hospital', 'A major Atlanta hospital system running a dedicated summer teen volunteer program for students interested in healthcare careers.', 'https://www.piedmont.org', 'https://www.google.com/s2/favicons?domain=www.piedmont.org&sz=128', 'medicine', array['counts for school hours', 'recurring'], false, false, 16, 'United States', 'GA', 'Atlanta', true, true, 'one-time', false),
  ('a1000000-0000-4000-8000-000000000011', null, 'Agape Youth and Family Center', 'A youth and family services organization on Atlanta west side offering after-school tutoring, mentoring, and family support programs.', 'https://agapeatlanta.org', 'https://www.google.com/s2/favicons?domain=agapeatlanta.org&sz=128', 'education', array['recurring', 'counts for school hours'], false, false, 14, 'United States', 'GA', 'Atlanta', true, true, 'ongoing', false),
  ('a1000000-0000-4000-8000-000000000012', null, 'The Study Hall', 'A nonprofit connecting volunteer tutors with students who need reading and academic support, run through community and school partner sites around Atlanta.', 'https://thestudyhall.org', 'https://www.google.com/s2/favicons?domain=thestudyhall.org&sz=128', 'education', array['recurring', 'counts for school hours'], false, false, 14, 'United States', 'GA', 'Atlanta', true, true, 'ongoing', false),
  ('a1000000-0000-4000-8000-000000000013', null, 'High Museum of Art', 'The leading art museum in the Southeast, with a large docent program and a dedicated Teen Team for high schoolers interested in museum work.', 'https://high.org', 'https://www.google.com/s2/favicons?domain=high.org&sz=128', 'art', array['recurring', 'leadership role'], false, false, 14, 'United States', 'GA', 'Atlanta', true, true, 'ongoing', false),
  ('a1000000-0000-4000-8000-000000000014', null, 'MOCA GA', 'The Museum of Contemporary Art of Georgia, showcasing work by living Georgia-connected artists and relying on volunteers to run gallery operations and events.', 'https://mocaga.org', 'https://www.google.com/s2/favicons?domain=mocaga.org&sz=128', 'art', array['recurring'], false, false, 14, 'United States', 'GA', 'Atlanta', true, true, 'both', false),
  ('a1000000-0000-4000-8000-000000000015', null, 'Meals on Wheels Atlanta', 'A Fulton County program delivering meals and pantry supplies to homebound, low-income seniors age 60 and up across central Atlanta.', 'https://www.mowatl.org', 'https://www.google.com/s2/favicons?domain=www.mowatl.org&sz=128', 'seniors', array['recurring'], false, false, 16, 'United States', 'GA', 'Atlanta', true, true, 'ongoing', false),
  ('a1000000-0000-4000-8000-000000000016', null, 'JF&CS Atlanta', 'Jewish Family & Career Services of Atlanta runs the One Good Deed program pairing adult volunteers with older adults living independently who could use extra support and company.', 'https://jfcsatl.org', 'https://www.google.com/s2/favicons?domain=jfcsatl.org&sz=128', 'seniors', array['recurring'], false, false, 25, 'United States', 'GA', 'Atlanta', true, true, 'ongoing', false),
  ('a1000000-0000-4000-8000-000000000017', null, 'A.G. Rhodes', 'A nonprofit network of senior care and rehabilitation centers across metro Atlanta, relying on volunteers to bring activities and companionship to residents.', 'https://www.agrhodes.org', 'https://www.google.com/s2/favicons?domain=www.agrhodes.org&sz=128', 'seniors', array['recurring', 'creative work'], false, false, 14, 'United States', 'GA', 'Atlanta', true, true, 'both', false),
  ('a1000000-0000-4000-8000-000000000018', null, 'Food Well Alliance', 'A nonprofit supporting more than 300 community gardens, orchards, and urban farms across metro Atlanta, coordinating volunteer workdays at gardens that need extra hands.', 'https://www.foodwellalliance.org', 'https://www.google.com/s2/favicons?domain=www.foodwellalliance.org&sz=128', 'gardening', array['outdoors', 'good for crews', 'physical work'], false, false, 12, 'United States', 'GA', 'Atlanta', true, true, 'both', false),
  ('a1000000-0000-4000-8000-000000000019', null, 'Truly Living Well Center for Urban Agriculture', 'An urban agriculture nonprofit running working farms on Atlanta west side that grow food, train new farmers, and welcome volunteers of every age and background.', 'https://www.trulylivingwell.com', 'https://www.google.com/s2/favicons?domain=www.trulylivingwell.com&sz=128', 'gardening', array['outdoors', 'physical work', 'family friendly'], false, false, 0, 'United States', 'GA', 'Atlanta', true, true, 'both', false),
  ('a1000000-0000-4000-8000-000000000020', null, 'Veterans Empowerment Organization', 'An Atlanta nonprofit providing housing, wellness programs, and job readiness training to help homeless veterans rebuild their lives.', 'https://www.veohero.org', 'https://www.google.com/s2/favicons?domain=www.veohero.org&sz=128', 'veterans', array['recurring'], false, false, 18, 'United States', 'GA', 'Atlanta', true, true, 'ongoing', false),
  ('a1000000-0000-4000-8000-000000000021', null, 'The Warrior Alliance', 'An Atlanta-based organization improving quality of life for service members, veterans, and their families through benefits navigation, legal support, and community programs.', 'https://thewarrioralliance.org', 'https://www.google.com/s2/favicons?domain=thewarrioralliance.org&sz=128', 'veterans', array['recurring'], false, false, 18, 'United States', 'GA', 'Atlanta', true, true, 'both', false),
  ('a1000000-0000-4000-8000-000000000022', null, 'Soldiers'' Angels', 'A national veteran and military family support organization with an active Atlanta volunteer presence, running letter-writing, care package, and support programs.', 'https://soldiersangels.org', 'https://www.google.com/s2/favicons?domain=soldiersangels.org&sz=128', 'veterans', array['creative work', 'family friendly'], false, false, 13, 'United States', 'GA', 'Atlanta', true, true, 'both', false),
  ('a1000000-0000-4000-8000-000000000023', null, 'Special Olympics Georgia', 'The Georgia chapter of Special Olympics, providing year-round sports training and competition for children and adults with intellectual disabilities across the state.', 'https://www.specialolympicsga.org', 'https://www.google.com/s2/favicons?domain=www.specialolympicsga.org&sz=128', 'sports', array['recurring', 'leadership role'], false, false, 14, 'United States', 'GA', 'Georgia', true, true, 'both', false),
  ('a1000000-0000-4000-8000-000000000024', null, 'Boys & Girls Clubs of Metro Atlanta', 'A network of 26 clubs across 9 metro Atlanta counties serving nearly 8,000 kids and teens each year with after-school programs, sports, and mentoring.', 'https://bgcma.org', 'https://www.google.com/s2/favicons?domain=bgcma.org&sz=128', 'sports', array['recurring', 'leadership role'], false, false, 16, 'United States', 'GA', 'Atlanta', true, true, 'ongoing', false)
on conflict (id) do nothing;

insert into public.opportunities
  (id, org_id, title, category, description, tags, min_age, remote, is_online, is_ongoing,
   hours_estimate, signup_link, external_url, starts_at, city, state)
values
  ('a2000000-0000-4000-8000-000000000001', 'a1000000-0000-4000-8000-000000000001', 'Assemble Meal Kits and Serve at HOPE Atlanta', 'community', 'Volunteers assemble meal kits and help in the community kitchen at HOPE Atlanta main office in Midtown, with most shifts running Tuesday through Friday during business hours and a few Saturday dates through the year. Volunteers must be at least 14, and those 14 to 17 need a parent or guardian present during the shift. It is a solid, low-barrier way to see homelessness prevention work up close in your own city.', array['good for crews', 'counts for school hours'], 14, false, false, true, '2-3 hrs', 'https://hopeatlanta.org/volunteer/', 'https://hopeatlanta.org/volunteer/', '2026-01-01T00:00:00Z', 'Atlanta', 'GA'),
  ('a2000000-0000-4000-8000-000000000002', 'a1000000-0000-4000-8000-000000000002', 'Support Atlanta Mission Shelters and Thrift Stores', 'community', 'Volunteers help staff thrift stores around Georgia, organize donation drives, and build care kits for people living at Atlanta Mission campuses. Volunteers must be at least 13 to serve at their campuses and 16 to serve a meal in their kitchens, and anyone under 18 needs to be accompanied by an adult. It is flexible enough for a single group project or an ongoing commitment.', array['good for crews', 'family friendly'], 13, false, false, true, '2-3 hrs', 'https://atlantamission.org/get-involved/volunteer/', 'https://atlantamission.org/get-involved/volunteer/', '2026-01-01T00:00:00Z', 'Atlanta', 'GA'),
  ('a2000000-0000-4000-8000-000000000003', 'a1000000-0000-4000-8000-000000000003', 'Volunteer at Covenant House Georgia', 'community', 'Volunteers can take on recreation, gardening, clothing closet, or life-skills roles, or help prepare and share a meal with residents. Every new individual volunteer must be at least 18 and attend an orientation before their first shift, which makes this a good option once you age into it during or after high school.', array['recurring'], 18, false, false, true, '2-3 hrs', 'https://covenanthousega.org/', 'https://covenanthousega.org/', '2026-01-01T00:00:00Z', 'Atlanta', 'GA'),
  ('a2000000-0000-4000-8000-000000000004', 'a1000000-0000-4000-8000-000000000004', 'Join a Pebble Tossers Family or Teen Project', 'community', 'Pebble Tossers matches families and teens with real projects at dozens of Atlanta nonprofits, and its Teen Leadership Program gives high schoolers a structured way to build service hours and leadership experience over time. Because Pebble Tossers itself vets every partner nonprofit, it is a good starting point if you are not sure which cause to pick yet.', array['family friendly', 'counts for school hours', 'leadership role'], 11, false, false, true, '2-3 hrs', 'https://pebbletossers.org/', 'https://pebbletossers.org/', '2026-01-01T00:00:00Z', 'Atlanta', 'GA'),
  ('a2000000-0000-4000-8000-000000000005', 'a1000000-0000-4000-8000-000000000005', 'Plant and Care for Trees Around Atlanta', 'environment', 'Trees Atlanta runs volunteer projects across the city almost every week, from tree plantings to invasive species removal to nursery work, so there is almost always a shift that fits your schedule. No experience is required and tools and training are provided on site, making it an easy repeat activity if you want a recurring outdoor commitment.', array['outdoors', 'physical work', 'recurring'], 12, false, false, true, '2-3 hrs', 'https://www.treesatlanta.org/get-involved/volunteer-as-an-individual/', 'https://www.treesatlanta.org/get-involved/volunteer-as-an-individual/', '2026-01-01T00:00:00Z', 'Atlanta', 'GA'),
  ('a2000000-0000-4000-8000-000000000006', 'a1000000-0000-4000-8000-000000000006', 'Restore Trails Along the Chattahoochee River', 'environment', 'Volunteers help restore trails, clean up the riverbanks, and support broader conservation projects across the Chattahoochee River National Recreation Area. Projects run throughout the year and range from single cleanup days to longer trail-building projects, so you can pick a level of commitment that fits.', array['outdoors', 'physical work', 'good for crews'], 14, false, false, true, '2-4 hrs', 'https://www.chattahoocheeparks.org/volunteer', 'https://www.chattahoocheeparks.org/volunteer', '2026-01-01T00:00:00Z', 'Atlanta', 'GA'),
  ('a2000000-0000-4000-8000-000000000007', 'a1000000-0000-4000-8000-000000000007', 'Volunteer with a Georgia Environmental Nonprofit', 'environment', 'EarthShare Georgia connects volunteers with hands-on projects run by its member environmental organizations across the state, from habitat restoration to educational events. It is a good way to sample a few different environmental causes before settling into one.', array['outdoors', 'good for crews'], 14, false, false, true, 'Varies', 'https://earthsharega.org/get-involved/volunteer', 'https://earthsharega.org/get-involved/volunteer', '2026-01-01T00:00:00Z', 'Atlanta', 'GA'),
  ('a2000000-0000-4000-8000-000000000008', 'a1000000-0000-4000-8000-000000000008', 'Support Georgia Wildlife Conservation', 'environment', 'Volunteers help with habitat restoration projects, wildlife garden certification outreach, and educational events across the state. It is a strong pick if you are specifically interested in wildlife and native habitat rather than general park cleanups.', array['outdoors', 'good for crews'], 14, false, false, true, 'Varies', 'https://gwf.org/volunteer/', 'https://gwf.org/volunteer/', '2026-01-01T00:00:00Z', 'Georgia', 'GA'),
  ('a2000000-0000-4000-8000-000000000009', 'a1000000-0000-4000-8000-000000000009', 'Join the CHOA VolunTEEN Summer Program', 'medicine', 'The VolunTEEN Program runs for eight weeks each summer for students 15 to 18, with volunteers committing to at least one three-hour shift a week bringing comfort and activities to patients across the hospital. Applications open once a year (typically opening around February for that summer), so plan ahead and check the site for the current application window.', array['counts for school hours', 'recurring'], 15, false, false, true, '3 hrs / week', 'https://www.choa.org/donors-and-volunteers/volunteer/teen-volunteers', 'https://www.choa.org/donors-and-volunteers/volunteer/teen-volunteers', '2026-01-01T00:00:00Z', 'Atlanta', 'GA'),
  ('a2000000-0000-4000-8000-000000000010', 'a1000000-0000-4000-8000-000000000010', 'Volunteer as a Piedmont Atlanta Teen', 'medicine', 'The summer teen program runs for about eight weeks and is open to students 16 and up (16 by June 1), who commit to one consistent shift per week supporting hospital and clinic departments while learning about healthcare careers. It is a strong choice if you are considering nursing, medicine, or another health profession.', array['counts for school hours', 'recurring'], 16, false, false, true, '3-4 hrs / week', 'https://www.piedmont.org/get-involved/volunteer/volunteer-at-piedmont-atlanta/teen-volunteers', 'https://www.piedmont.org/get-involved/volunteer/volunteer-at-piedmont-atlanta/teen-volunteers', '2026-01-01T00:00:00Z', 'Atlanta', 'GA'),
  ('a2000000-0000-4000-8000-000000000011', 'a1000000-0000-4000-8000-000000000011', 'Be a Literacy Leader or Homework Buddy', 'education', 'Volunteers work one-on-one with students to strengthen reading and writing skills through the Literacy Leader program, or help with daily homework support through Homework Buddies, Monday through Thursday while Atlanta Public Schools are in session. It is a good option if you want a consistent, recurring mentoring relationship rather than a single event.', array['recurring', 'counts for school hours'], 14, false, false, true, '1-2 hrs / week', 'https://agapeatlanta.org/welcome-volunteers-2/', 'https://agapeatlanta.org/welcome-volunteers-2/', '2026-01-01T00:00:00Z', 'Atlanta', 'GA'),
  ('a2000000-0000-4000-8000-000000000012', 'a1000000-0000-4000-8000-000000000012', 'Tutor a Student in Reading', 'education', 'Volunteers commit to at least one weekday afternoon a week reading with children one-on-one or in small groups at a partner site. Training is provided, and it is one of the more consistent, relationship-based tutoring options in the metro area.', array['recurring', 'counts for school hours'], 14, false, false, true, '1-2 hrs / week', 'https://thestudyhall.org/volunteer/', 'https://thestudyhall.org/volunteer/', '2026-01-01T00:00:00Z', 'Atlanta', 'GA'),
  ('a2000000-0000-4000-8000-000000000013', 'a1000000-0000-4000-8000-000000000013', 'Become a Gallery Guide or Join Teen Team', 'art', 'The High trains volunteer docents to lead interactive tours and gallery talks, with over 140 docents giving around 3,000 tours a year, and its Teen Team lets high schoolers create their own teen-led gallery guide experiences. It is a great fit if you love art and public speaking.', array['recurring', 'leadership role'], 14, false, false, true, '2-3 hrs / week', 'https://high.org/volunteer/', 'https://high.org/volunteer/', '2026-01-01T00:00:00Z', 'Atlanta', 'GA'),
  ('a2000000-0000-4000-8000-000000000014', 'a1000000-0000-4000-8000-000000000014', 'Greet Visitors or Train as a MOCA GA Docent', 'art', 'Volunteers can greet visitors and share exhibition information, help facilitate special events, or train to become a docent, and committed volunteers receive a waived one-year family membership. It is a smaller, more personal museum setting than the High if you want more hands-on responsibility sooner.', array['recurring'], 14, false, false, true, '2-3 hrs', 'https://mocaga.org/contribute/volunteering/', 'https://mocaga.org/contribute/volunteering/', '2026-01-01T00:00:00Z', 'Atlanta', 'GA'),
  ('a2000000-0000-4000-8000-000000000015', 'a1000000-0000-4000-8000-000000000015', 'Deliver Meals to Homebound Seniors', 'seniors', 'Volunteers deliver meals along a set route or help with food distribution days, spending a few minutes at each stop to check in and make sure the senior on the route is doing okay. Routes typically take about an hour and can become a regular weekly commitment.', array['recurring'], 16, false, false, true, '1 hr / route', 'https://www.mowatl.org/', 'https://www.mowatl.org/', '2026-01-01T00:00:00Z', 'Atlanta', 'GA'),
  ('a2000000-0000-4000-8000-000000000016', 'a1000000-0000-4000-8000-000000000016', 'Become a Friendly Visitor Through One Good Deed', 'seniors', 'Volunteers visit their matched older adult for at least two hours, twice a month, helping with errands, a shared meal, or just an afternoon out together. Because it is an ongoing one-on-one relationship, volunteers must be at least 25, making this a great option to bookmark for college or after.', array['recurring'], 25, false, false, true, '2 hrs / visit', 'https://jfcsatl.org/services/aviv-older-adults/one-good-deed', 'https://jfcsatl.org/services/aviv-older-adults/one-good-deed', '2026-01-01T00:00:00Z', 'Atlanta', 'GA'),
  ('a2000000-0000-4000-8000-000000000017', 'a1000000-0000-4000-8000-000000000017', 'Bring Activities to Senior Care Residents', 'seniors', 'Volunteers lead games, music, crafts, or simple conversation with residents at A.G. Rhodes senior care centers, with roles available for both one-time events and ongoing weekly visits. It is a good option if you enjoy spending time with older adults in a more structured care setting.', array['recurring', 'creative work'], 14, false, false, true, '1-2 hrs', 'https://www.agrhodes.org/volunteer/volunteer-opportunities/', 'https://www.agrhodes.org/volunteer/volunteer-opportunities/', '2026-01-01T00:00:00Z', 'Atlanta', 'GA'),
  ('a2000000-0000-4000-8000-000000000018', 'a1000000-0000-4000-8000-000000000018', 'Help at a Metro Atlanta Community Garden Workday', 'gardening', 'Volunteer workdays rotate through different community gardens around the metro area, with common tasks like weeding, turning compost, spreading mulch, and general garden beautification. It is a flexible, drop-in-friendly way to support local food security.', array['outdoors', 'good for crews', 'physical work'], 12, false, false, true, '2-3 hrs', 'https://www.foodwellalliance.org/volunteer-experience', 'https://www.foodwellalliance.org/volunteer-experience', '2026-01-01T00:00:00Z', 'Atlanta', 'GA'),
  ('a2000000-0000-4000-8000-000000000019', 'a1000000-0000-4000-8000-000000000019', 'Volunteer on a Working Urban Farm', 'gardening', 'Volunteers help with planting, harvesting, and general farm upkeep at Truly Living Well working farm sites, with the organization explicitly welcoming volunteers from every walk of life and age range. It is one of the most family-friendly hands-on options in the city.', array['outdoors', 'physical work', 'family friendly'], 0, false, false, true, '2-3 hrs', 'https://www.trulylivingwell.com/', 'https://www.trulylivingwell.com/', '2026-01-01T00:00:00Z', 'Atlanta', 'GA'),
  ('a2000000-0000-4000-8000-000000000020', 'a1000000-0000-4000-8000-000000000020', 'Support Homeless Veterans at VEO', 'veterans', 'Volunteers support VEO campus programs across housing, wellness, and workforce readiness for veterans working to get back on their feet. Roles and schedules vary, so reach out through the site to find a fit for your availability.', array['recurring'], 18, false, false, true, 'Varies', 'https://www.veohero.org/', 'https://www.veohero.org/', '2026-01-01T00:00:00Z', 'Atlanta', 'GA'),
  ('a2000000-0000-4000-8000-000000000021', 'a1000000-0000-4000-8000-000000000021', 'Volunteer with The Warrior Alliance', 'veterans', 'Volunteers support community initiatives that help veterans understand and access their benefits and connect with legal counsel when needed. It is a good fit if you want to support veterans through practical, advocacy-adjacent work rather than direct service delivery.', array['recurring'], 18, false, false, true, 'Varies', 'https://thewarrioralliance.org/', 'https://thewarrioralliance.org/', '2026-01-01T00:00:00Z', 'Atlanta', 'GA'),
  ('a2000000-0000-4000-8000-000000000022', 'a1000000-0000-4000-8000-000000000022', 'Support Veterans and Military Families in Atlanta', 'veterans', 'Local Atlanta volunteers help assemble care packages, write letters, and support events honoring veterans and active-duty service members, with time commitments ranging from a few hours a month to as often as your schedule allows. It is a flexible option if you want to help but cannot commit to a strict weekly schedule.', array['creative work', 'family friendly'], 13, false, false, true, 'Varies', 'https://soldiersangels.org/location/atlanta-ga/', 'https://soldiersangels.org/location/atlanta-ga/', '2026-01-01T00:00:00Z', 'Atlanta', 'GA'),
  ('a2000000-0000-4000-8000-000000000023', 'a1000000-0000-4000-8000-000000000023', 'Coach or Volunteer at Special Olympics Georgia', 'sports', 'Volunteers can train and certify as a coach or assistant coach, committing to practices once or twice a week for 8 to 10 weeks before state competitions, or join a State Games Organizing Committee helping plan events. No sports expertise is required, just a willingness to work closely with athletes.', array['recurring', 'leadership role'], 14, false, false, true, '1-2 hrs / week', 'https://www.specialolympicsga.org/volunteer/', 'https://www.specialolympicsga.org/volunteer/', '2026-01-01T00:00:00Z', 'Georgia', 'GA'),
  ('a2000000-0000-4000-8000-000000000024', 'a1000000-0000-4000-8000-000000000024', 'Coach Youth Sports at a Local Club', 'sports', 'Volunteers coach kids ages 6 to 18 in structured team sports like flag football, basketball, and soccer, teaching teamwork and sportsmanship during afternoon sessions Monday through Friday. It is a strong pick if you want a regular, recurring coaching role close to home.', array['recurring', 'leadership role'], 16, false, false, true, '2-4 hrs / week', 'https://bgcma.org/get-involved/volunteer/', 'https://bgcma.org/get-involved/volunteer/', '2026-01-01T00:00:00Z', 'Atlanta', 'GA')
on conflict (id) do nothing;
